<script setup lang="ts">
import { t as uiText } from '@/locales'

import {computed} from 'vue'
import type {RouteNode,RouteEdge} from '@/api/modules/masterData'
const props=defineProps<{graph:{nodes:RouteNode[];edges:RouteEdge[]}}>()
const names=computed(()=>new Map(props.graph.nodes.map(n=>[n.id,n.name])))
</script>
<template><section class="process-graph" :aria-label='uiText("工艺节点与依赖")'><h4>{{graph.nodes.length}}{{ uiText(" 个节点 · ") }}{{graph.edges.length}}{{ uiText(" 条明确连接") }}</h4><ol><li v-for="n in graph.nodes" :key="n.id"><div><strong>{{n.stepNo}} · {{n.name}}</strong><code>{{n.nodeCode}}</code><small>{{ uiText("工序 ") }}{{n.operationCode}}{{ uiText(" · 本地节点 ") }}{{n.localNodeCode||uiText('未提供')}}</small></div><div><small>{{ uiText("前置：") }}{{graph.edges.filter(e=>e.toNodeId===n.id).map(e=>names.get(e.fromNodeId)).join('、')||uiText('起始节点')}}</small><small>{{ uiText("后置：") }}{{graph.edges.filter(e=>e.fromNodeId===n.id).map(e=>names.get(e.toNodeId)).join('、')||uiText('结束节点')}}</small></div><details><summary>{{ uiText("MES 原节点配置（只读）") }}</summary><pre>{{JSON.stringify(n.config,null,2)}}</pre></details></li></ol><div class="edge" v-for="e in graph.edges" :key="e.id"><span>{{names.get(e.fromNodeId)}}</span><b>→</b><span>{{names.get(e.toNodeId)}}</span><small>{{e.relationType}} {{uiText(String((e.label) ?? ''))}}</small></div></section></template>
<style scoped>.process-graph{min-width:0;container-type:inline-size}.process-graph h4{margin:8px 0}.process-graph ol{list-style:none;padding:0;margin:0}.process-graph li{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(0,1fr);gap:8px;border-bottom:1px solid var(--el-border-color-lighter);padding:8px 0}.process-graph li>div{min-width:0}.process-graph small,.process-graph code{display:block;overflow-wrap:anywhere}.process-graph small{color:var(--el-text-color-secondary);font-size:12px}.process-graph details{grid-column:1/-1;font-size:12px}.process-graph pre{white-space:pre-wrap;overflow-wrap:anywhere}.edge{display:flex;gap:8px;flex-wrap:wrap;padding:5px 0}@container(max-width:550px){.process-graph li{grid-template-columns:1fr}}</style>
